update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p076","body":"ایک سپنہ سہی\nانجان اپنا کوئی\nساحل پہ اترتی\nابھرتی سی لہر\nتم ہو\n\nرنج کوئی ، آس میری\nدور سہی ، پاس کہیں\nچاندنی شب کی سرد\nگزرتی سی پہر\nتم ہو\n\nنیا رستہ کوئی\nکوئی منزل نئی\nپر اسرار ، گلزار\nنیا سا دل کا نگر\nتم ہو\n\nان کہی سی آواز\nدھڑکتے دل کی ساز\nہزار پردوں میں چھپا راز\nچپ ، ناراض اور بےاثر\nتم ہو\n\nمیرے قلم کی روانی\nچنچل شوخ جوانی\nکچھ افسردہ ، ذرا نادانی\nبہکی سی پہلی نظر\nتم ہو\n\nلفظوں میں، گلوں میں\nبہاروں میں ،ساونوں میں\nقافلوں میں ، فاصلوں میں\nصبر کا میٹھا ثمر\nتم ہو"},{"slug":"tum-p077","body":"اکیلے چلنا آوارگی ہے کیوں\nتیرا ہونا ہی زندگی ہے کیوں\n\nسویروں میں اندھیر نگری ڈوب چلی ہے\nاس قدر یہ دل اداس بھی ہے کیوں\n\nتھک ہار کے ابھی آنکھ لگی ہی تھی\nپھر سے تیری آواز سنی ہے کیوں\n\nدل تیرے دامن سے چاک چاک ہوا\nآنکھ مگر تجھ کو ڈھونڈتی ہے کیوں\n\nزندگی مجھ کو بھی تو عطا کی یے\nزندگی مجھ میں تیری کمی ہے کیوں\n\nمجھ کو تو کسی نے مانگا ہی نہیں\nمجھ میں یہ محبت پلی ہے کیوں\n\nاحمد ؔ  تمہیں کبھی اس طرح نہیں دیکھا\nآج ان آنکھوں میں یہ نمی ہے کیوں"},{"slug":"tum-p078","body":"مجھے تم یاد آئے\nجب ساون نے برسنا چاہا\nجب بادلوں نے گرجنا چاہا\nجب ستاروں نے دمکنا چاہا\nجب بادلوں کی اوٹ میں\nچاند نے چھپنا چاہا\nجب اوس بھری لکڑیوں نے\nٹھنڈے آسمان تلے جلنا چاہا\nمجھے تم یاد آئے\n\nجب بھی کسی نے حسن کا ذکر کیا\nتیرے ملنے کا ہم نے بہت شکر کیا\nصنف نظر کیا میں نے آہوں کو\nفقط محبت ہی کو امر کیا\nجب کبھی خار گلوں سے جڑے دیکھے\nمیں نے اپنے اجڑے ہوئے سپنے دیکھے\nجب کبھی بہاروں نے پھول کھلائے\nگلوں نے آس پاس کے منظر مہکائے\nجب کوئی دور سے ہاتھ ہلائے\nجب مجھے کوئی تم بلائے\nمجھے تم یاد آئے\n\nٹوٹے ستارے کے گرنے پر\nکسی کے کسی سے بچھڑنے پر\nامیدوں کے چراغ بجھنے پر\nمنزل سے رستہ بھٹکنے پر\nزار زار رونے پر\nبلاوجہ ہنسنے پر\nوحشت زدہ چپ میں\nدل آویز صداوں میں\nصبح سویرے باد صبا سے\nشام کی ٹھنڈی ہواوں میں\nمجھے تم یاد آئے!"},{"slug":"tum-p079","body":"دوستی ، محبت اور آشنائی سے\nکچھ اثر نہ ہوا مسیحائی سے\n\nنظر ساری عمر جس کی تلاش میں رہی\nوہ نظر جو ملی تو ملی ہرجائی سے\n\nتیرے ہاتھوں ہونا تھا دل کا زیاں لازم\nکون ٹال سکتا ہے آنے کو آئی سے\n\nگزری قفس میں زندگانی جن پرندوں کی\nاثر کیا ان کو پھر چمن کی جدائی سے\n\nاحمد ؔ یہ جن مریضوں کو عشق نے مار ڈالا ہے\nانھیں کیا غرض دعائی سے ، انھیں کیا غرض دوائی سے"},{"slug":"tum-p080","body":"یاد آئے ہو تو اب بھلاتے جانا\nدل کا کام ہے تجھ پہ آتے جانا\n\nکبھی آنا زمانے کے ستم کھا کر تم\nکبھی تو چین سے مجھ کو سلاتے جانا\n\nبے درد ہوا بن کے آنگن میں اترنا کبھی\nکبھی سپنوں کے دیپ جلاتے جانا\n\nزندگی کب جانے دوریوں میں بٹ جائے گی\nکبھی گزر ہو تو فاصلے مٹاتے جانا\n\nخواب سارے پلکوں پہ سجا کر\nہو سکے تو پلکیں جھپکاتے جانا\n\nکیا ہوا جو بنے ہیں دوست رقیب\nاپنی جانب سے تم تو نبھاتے جانا\n\nیہ ترک تعلق اگرچہ ضروری ہے مگر\nاحمد ؔ جاتے جاتے تم ہاتھ ملاتے جانا"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
